  shareSubtitle: "\uC885\uD569\uC810\uC218(\uB51C+\uCD1D\uB51C) \uC21C\uC704 \xB7 \uBA54\uAC00\xB7\uC100\uB3C4\uC6B0 \uD3EC\uD568",
  shareButton: "\u{1F4F8} \uC774 \uD2F0\uC5B4\uD45C \uC774\uBBF8\uC9C0\uB85C \uACF5\uC720\xB7\uC800\uC7A5",
  shareFooter: "\uD3EC\uCF13\uBAACGO \uB808\uC774\uB4DC \uB51C\uB7EC \uD2F0\uC5B4",
  explainerH: "\uC885\uD569\uC810\uC218\uB294 \uC5B4\uB5BB\uAC8C \uACC4\uC0B0\uD588\uB098\uC694?",
  explainerBody: "\uACF5\uAC1C \uAC8C\uC784 \uB370\uC774\uD130(\uC885\uC871\uAC12\xB7\uAE30\uC220 \uC704\uB825/\uC2DC\uC804\uC2DC\uAC04/\uC5D0\uB108\uC9C0)\uB85C \uD45C\uC900 PvE \uACF5\uC2DD\uC744 \uC801\uC6A9\uD588\uC2B5\uB2C8\uB2E4. \uC774 \uC18D\uC131\uC5D0 \uC57D\uC810\uC778 \uB300\uC0C1\uC744 \uB808\uBCA840\uC73C\uB85C \uB54C\uB9B4 \uB54C \uAE30\uC900\uC785\uB2C8\uB2E4. \uB51C(DPS)\uC740 STAB\xB7\uC57D\uC810 1.6\uBC30 \uBC18\uC601 \uCD08\uB2F9 \uB370\uBBF8\uC9C0, \uCD1D\uB51C(TDO)\uC740 \uBC84\uD2F0\uB294 \uC2DC\uAC04(\uCCB4\uB825\xB7\uBC29\uC5B4)\uAE4C\uC9C0 \uBC18\uC601\uD55C \uAE30\uC808 \uC804 \uCD1D \uB370\uBBF8\uC9C0, \uC885\uD569\uC810\uC218\uB294 \uC774 \uB458\uC744 \uACB0\uD569\uD55C \uADE0\uD615 \uC9C0\uD45C(\uB51C\xB3\xD7\uCD1D\uB51C)\uB85C \uC21C\uC704\uB97C \uB9E4\uAE41\uB2C8\uB2E4(\uD3EC\uCF13\uBC30\uD2C0\uB7EC Overall \uBC29\uC2DD). \uACC4\uC0B0 \uBC29\uC2DD\uC5D0 \uB530\uB77C \uB2E4\uB978 \uC0AC\uC774\uD2B8\uC640 \uC218\uCE58\uAC00 \uB2E4\uB97C \uC218 \uC788\uC73C\uB2C8 \uCC38\uACE0\uC6A9\uC73C\uB85C \uBD10\uC8FC\uC138\uC694.",
  otherTypes: "\uB2E4\uB978 \uC18D\uC131 \uD2F0\uC5B4\uD45C \u2192",
