  metaTitle: "\uD3EC\uCF13\uBAAC \uD2F0\uC5B4 \xB7 \uB808\uC774\uB4DC \uCD5C\uAC15 \uB51C\uB7EC DPS \uC21C\uC704\uD45C | GBL Note",
  metaDesc: "\uB808\uC774\uB4DC \uCD5C\uAC15 \uB51C\uB7EC TOP 30 \u2014 \uC2E4\uCE21 DPS\xB7\uB0B4\uAD6C(TDO) \uC885\uD569 \uC21C\uC704. \uBA54\uAC00\xB7\uC6D0\uC2DC\xB7\uC100\uB3C4\uC6B0 \uD3EC\uD568, \uB51C\uB7EC\uBCC4 \uCD94\uCC9C \uAE30\uC220\uBC30\uCE58\uAE4C\uC9C0 \uD55C\uB208\uC5D0. \uB9E4\uC8FC \uC790\uB3D9 \uAC31\uC2E0.",
  metaTitleF: (ty, top1) => `\uD3EC\uCF13\uBAAC\uACE0 ${ty} \uB808\uC774\uB4DC \uB51C\uB7EC \uC21C\uC704 \u2014 1\uC704 ${top1} \xB7 DPS \uD2F0\uC5B4\uD45C | GBL Note`,
