  explainerBody: "\uD2F0\uC5B4\uC640 \uCD94\uCC9C \uAE30\uC220\uBC30\uCE58\uB294 \uACF5\uAC1C \uC804\uD22C \uC2DC\uBBAC\uB808\uC774\uC158 \uB370\uC774\uD130(PvPoke)\uB97C \uAE30\uBC18\uC73C\uB85C \uC0B0\uCD9C\uD55C \uAC83\uC774\uBA70, \uC2E4\uCE21 \uD53D\uB960\uC740 GBL Note \uC0AC\uC6A9\uC790\uB4E4\uC774 \uC2E4\uC81C\uB85C \uB9CC\uB09C \uC0C1\uB300\uB97C \uC775\uBA85 \uC9D1\uACC4\uD55C \uAC12\uC785\uB2C8\uB2E4. \uC774\uB860\uC0C1 \uAC15\uD55C \uD3EC\uCF13\uBAAC\uACFC \uC2E4\uC81C\uB85C \uC720\uD589\uD558\uB294 \uD3EC\uCF13\uBAAC\uC744 \uD568\uAED8 \uBE44\uAD50\uD574\uBCF4\uC138\uC694.",
