  metaDesc: "S\uD2F0\uC5B4 \uCD5C\uAC15 \uD3EC\uCF13\uBAAC\uC740? \uD2F0\uC5B4\uD45C(S/A/B) + \uD3EC\uCF13\uBAAC\uBCC4 \uCD94\uCC9C \uAE30\uC220\uBC30\uCE58 + \uC720\uC800 \uC2E4\uCE21 \uD53D\uB960\uC744 \uD55C\uB208\uC5D0. \uC774\uB860 \uB7AD\uD0B9\uACFC \uC2E4\uC804 \uB370\uC774\uD130\uB97C \uD568\uAED8 \uBD10\uC11C \uC9C0\uAE08 \uBB58 \uD0A4\uC6B8\uC9C0 \uBC14\uB85C \uACB0\uC815.",
