  hubExplainH: "\uC218\uCE58\uB294 \uC5B4\uB514\uC11C \uB098\uC628 \uAC74\uAC00\uC694?",
  hubExplainBody: (d) => `\uC704\uB825\xB7\uC5D0\uB108\uC9C0\xB7\uD134\uC740 PvPoke \uACF5\uAC1C \uAC8C\uC784\uB9C8\uC2A4\uD130(${d}) \uAE30\uC900 PvP \uC218\uCE58\uC785\uB2C8\uB2E4(\uB808\uC774\uB4DC\xB7\uCCB4\uC721\uAD00 \uC218\uCE58\uC640 \uB2E4\uB985\uB2C8\uB2E4). DPT\xB7EPT\xB7DPE\uC640 \uD0C0\uC218, \uBA54\uD0C0 \uCC44\uC6A9 \uC218\uB294 GBL Note\uAC00 \uADF8 \uC218\uCE58\uC640 \uD604\uC7AC \uC2DC\uC98C \uD2F0\uC5B4 \uB370\uC774\uD130\uB85C \uACC4\uC0B0\uD588\uC2B5\uB2C8\uB2E4. \uBC38\uB7F0\uC2A4 \uD328\uCE58\uAC00 \uC788\uC73C\uBA74 \uB2E4\uC2DC \uACC4\uC0B0\uD574 \uAC31\uC2E0\uD569\uB2C8\uB2E4.`,
  back: "\u2190 \uAE30\uC220 \uB3C4\uAC10",
