  metaDesc: (n, k) => `${n}(${k})\uC758 PvP \uC704\uB825\xB7\uC5D0\uB108\uC9C0\xB7\uD134, \uB178\uBA40 \uAE30\uC220\uBCC4 \uD0C0\uC218, \uC774\uBC88 \uC2DC\uC98C \uC774 \uAE30\uC220\uC744 \uC4F0\uB294 \uBA54\uD0C0 \uD3EC\uCF13\uBAAC\uACFC \uC608\uC0C1 \uB370\uBBF8\uC9C0, \uBC30\uC6B8 \uC218 \uC788\uB294 \uD3EC\uCF13\uBAAC \uC804\uCCB4.`,
  h1Suffix: "PvP \uC218\uCE58 \xB7 \uD0C0\uC218 \xB7 \uC0AC\uC6A9 \uD3EC\uCF13\uBAAC",
  rankOf: (r, t) => `${t}\uAC1C \uC911 ${r}\uC704`,
