  usersSub: (d, h) => `\uD604\uC7AC \uC2DC\uC98C \uCD94\uCC9C \uAE30\uC220\uBC30\uCE58 \uAE30\uC900. \uC608\uC0C1 \uB370\uBBF8\uC9C0\uB294 \uADF8 \uB9AC\uADF8 \uC0C1\uC704\uAD8C\uC758 \uC911\uC559\uAC12 \uC0C1\uB300(\uBC29\uC5B4 ${d} \xB7 HP ${h})\uC5D0\uAC8C \uC0C1\uC131 \uC911\uB9BD\uC73C\uB85C \uB9DE\uCDC4\uC744 \uB54C\uC758 \uAC12\uC785\uB2C8\uB2E4.`,
