  engineCredit: "\uACC4\uC0B0 \uC5D4\uC9C4\uC740 \uC624\uD508\uC18C\uC2A4 \uD504\uB85C\uC81D\uD2B8 PvPoke(MIT \uB77C\uC774\uC120\uC2A4 \xB7 \xA9 2019 pvpoke)\uB97C \uAE30\uBC18\uC73C\uB85C \uC2E4\uC81C \uBC30\uD2C0 \uBA54\uCEE4\uB2C8\uC998(\uB370\uBBF8\uC9C0\xB7\uC5D0\uB108\uC9C0\xB7\uC2E4\uB4DC AI\xB7\uBCA0\uC774\uD305)\uC744 \uC815\uBC00 \uACC4\uC0B0\uD569\uB2C8\uB2E4.",
  metaTitle: "\uD3EC\uCF13\uBAAC\uACE0 PvP \uBC30\uD2C0 \uC2DC\uBBAC\uB808\uC774\uD130 \xB7 \uAC1C\uCCB4\uAC12\xB7\uAE30\uC220 \uC9C0\uC815 | GBL Note",
  metaDesc: "\uD3EC\uCF13\uBAAC GO \uBC30\uD2C0\uB9AC\uADF8 1:1 \uC2DC\uBBAC\uB808\uC774\uD130. \uB450 \uD3EC\uCF13\uBAAC\uC758 \uAC1C\uCCB4\uAC12(\uACF5/\uBC29/\uCCB4)\xB7\uAE30\uC220\xB7\uB808\uBCA8\xB7\uADF8\uB9BC\uC790\xB7\uC2E4\uB4DC\uB97C \uC9C0\uC815\uD574 \uC2E4\uC81C \uBC30\uD2C0 \uACB0\uACFC\uB97C \uACC4\uC0B0. \uC288\uD37C\xB7\uD558\uC774\uD37C\xB7\uB9C8\uC2A4\uD130\uB9AC\uADF8.",
  metaKeywords: ["\uD3EC\uCF13\uBAAC\uACE0 \uBC30\uD2C0 \uC2DC\uBBAC\uB808\uC774\uD130", "PvP \uC2DC\uBBAC\uB808\uC774\uD130", "\uBC30\uD2C0\uB9AC\uADF8 \uC2DC\uBBAC", "\uD3EC\uCF13\uBAAC\uACE0 \uB9E4\uCE58\uC5C5", "1:1 \uBC30\uD2C0 \uACC4\uC0B0\uAE30"],
  ogTitle: "\uD3EC\uCF13\uBAAC\uACE0 PvP \uBC30\uD2C0 \uC2DC\uBBAC\uB808\uC774\uD130",
  ogDesc: "\uAC1C\uCCB4\uAC12\xB7\uAE30\uC220 \uC9C0\uC815 1:1 \uBC30\uD2C0 \uACC4\uC0B0"
